 void runPortamento(uint32_t input,uint32_t ret,bool realDsp=false){using T=kstation::MidiVoicePortamentoTask;kstation::NativeMidiVoicePortamento t(input,ret);unsigned n=0;while(!t.task().complete()){check(++n<100,"portamento hang");if(t.task().awaitingChild()){auto child=t.task().child();if(child==T::Child::VoiceAddress)runVoiceAddress();else if(child==T::Child::ContinueLong)runVoiceFinal(ret,realDsp);else if(realDsp&&(child==T::Child::SendFirst||child==T::Child::SendSecond)){const uint32_t next=child==T::Child::SendFirst?(t.task().alternate()?0x7532:0x7510):(t.task().alternate()?0x753e:0x751a);runVoiceUpdate(next);}else{auto at=uint32_t(a->getPC());auto u=a->memory[at],v=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,u);byte(at+1,v);}check(t.resumeChild(*b),"portamento resume");++children;continue;}check(t.step(*b),"portamento phase");a->step();equal();++phases;}}
